 svg=(O/'figures'/(f['id']+'.svg')).read_text();parts+=[f'<figure id="{f["id"]}"><div class="visual">{svg}</div><figcaption class="caption"><b>图{i+1} {f["title"]}。</b>{f["caption"]}</figcaption><div class="downloads"><a download href="figures/{f["id"]}.svg">SVG 矢量原图</a><a download href="figures/{f["id"]}.png">PNG 高清图</a></div></figure>']
